{
  "PROP-01b-partial-inv-011": {
    "property_id": "PROP-01b-partial-inv-011",
    "audit_result": {
      "property_id": "PROP-01b-partial-inv-011",
      "classification": "vulnerability",
      "code_path": "src/sales/LegionAbstractSale.sol::setAcceptedCapital::L436-442",
      "proof_trace": "The property requires both Merkle roots to be immutable after publishSaleResults(), but setAcceptedCapital() lacks the whenSaleResultsNotPublished guard that is applied to other post-publish-sensitive functions (cancel, transferInvestorPosition). It carries only onlyLegion + whenSaleNotCanceled guards, allowing overwrite of acceptedCapitalMerkleRoot at any time post-publication. claimTokensMerkleRoot is immutable (no setter), but acceptedCapitalMerkleRoot is not \u2014 proof fails at LegionAbstractSale.sol:438.",
      "attack_scenario": "The Legion admin calls publishSaleResults() to finalize accepted capital, then calls setAcceptedCapital(maliciousRoot) to replace acceptedCapitalMerkleRoot; investors whose proofs were valid against the original root can no longer call withdrawExcessInvestedCapital (L767 reverts), while investors with proofs against the new root gain access \u2014 enabling arbitrary post-hoc redistribution of accepted capital.",
      "checklist_id": "PROP-01b-partial-inv-011"
    },
    "text": "Merkle roots (claimMerkleRoot, acceptedCapitalMerkleRoot) are immutable after publishSaleResults.",
    "assertion": "publishSaleResults() sets roots AND no subsequent function modifies claimMerkleRoot or acceptedCapitalMerkleRoot",
    "covers": "SG-004",
    "severity": "CRITICAL",
    "type": "invariant"
  }
}

